import json, hashlib, re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
OUT=Path(__file__).resolve().parents[1]
G=json.loads((ROOT/'historiography-1920-2000.json').read_text())
C=json.loads((OUT/'framework-evidence/release-counts.json').read_text())

def source(url,title,scope,kind='publisher_description_or_contents'):
 return dict(url=url,title=title,source_type=kind,checked_on='2026-10-24',checked_scope=scope)

def candidate(key,label,pid,priority,kind,covered,gap,next_action,limits,workids,support,targets):
 p=C['people'][key]
 contexts=[]
 if pid:
  for n in G['nodes']:
   roster=[dict(role=x['role'],context=x['context'],works=x.get('works',''),source_ids=x.get('source_ids',[])) for x in n.get('representative_people',[]) if x['person_id']==pid]
   strands=[dict(strand_id=x['id'],title=x['title'],works=x.get('works',''),source_ids=x.get('source_ids',[])) for x in n.get('strands',[]) if pid in x.get('person_ids',[])]
   if roster or strands:contexts.append(dict(node_id=n['id'],label=n['label'],roster=roster,strands=strands))
 ids={x['id']:x for x in G['people']}
 works={x['work_id']:x for x in p['top_first_author_work_records']}
 return dict(candidate_id='framework_'+key.split('|')[0],person_key=key,label=label,status='research_candidate_only',priority=priority,gap_kind=kind,
  release_counts=dict(all_authorship_strict=p['recomputed_via_authorship_strict'],all_authorship_dated=p['recomputed_via_authorship_dated'],first_author_strict=p['recomputed_first_author_strict'],first_author_dated=p['recomputed_first_author_dated'],qid=p['release_record']['qid'],qid_basis=p['release_record']['qid_basis']),
  work_leads=[works[w] for w in workids],existing_graph=dict(person_id=pid,standalone_node_id=ids.get(pid,{}).get('node_id'),coverage_summary=covered,contexts=contexts),precise_missing_content=gap,recommended_next_action=next_action,proposed_research_context_ids=targets,
  confidence=dict(gap_detection='high',identity_and_scope_limits=limits,implementation_claim_support='Not yet accepted. Checked sources support the candidate work or framework, not an automatic influence or contribution edge.'),primary_supporting_sources=support)

