nodeids={n['id'] for n in G['nodes']}
for x in c:x['proposed_research_context_ids']=[i for i in x['proposed_research_context_ids'] if i in nodeids]
assert len(c)==12
for x in c:
 assert x['primary_supporting_sources']
 assert x['work_leads']
 for w in x['work_leads']:assert w['recomputed_strict_phds']==int(w['cited_by_strict_phds'])
# Normalize spacing in researcher-authored prose without changing release keys, URLs or verbatim coverage evidence.
def prose(s):
 return re.sub(r'(?<=[A-Za-z])(?=\d{2,})|(?<=\d)(?=[A-Za-z])', ' ', s)
for x in c:
 for field in ['precise_missing_content','recommended_next_action']:
  x[field]=prose(x[field])
 x['existing_graph']['coverage_summary']=prose(x['existing_graph']['coverage_summary'])
 for field,value in x['confidence'].items():x['confidence'][field]=prose(value)
 for z in x['primary_supporting_sources']:
  z['title']=prose(z['title']);z['checked_scope']=prose(z['checked_scope'])
report['scope_limits']=[prose(s) for s in report['scope_limits']]
for x in report['screened_but_not_queued']:
 for field in ['decision','reason']:x[field]=prose(x[field])
existing_source_ids={sid for x in c for n in x['existing_graph']['contexts'] for v in n['roster']+n['strands'] for sid in v['source_ids']}
existing_source_ids.update(['guha_elementary','pe137_guha_rule_of_property','spiegel_romancing_primary'])
report['existing_graph_source_evidence']=[dict(id=s['id'],title=s.get('title'),url=s.get('url'),verification=s.get('verification')) for s in G['sources'] if s['id'] in existing_source_ids]
report['existing_graph_source_evidence_note']='Verbatim scoped source metadata from the hashed canonical graph; these prior verification notes are not new primary readings by this reviewer.'
report['independent_count_recomputation']='Read the frozen dissertations table and retain in_analysis=True. Join citations to authorship for exact person keys and deduplicate dissertation IDs across all authorship positions; separately join works.first_author_key for first-author totals. Work leads count exact work_id citations. Dated counts require a nonempty integer dissertation year. All thirteen screened author-key all-authorship totals and every displayed work total matched the release values; first-author totals were independently computed rather than inferred from those totals.'
assert all(i in nodeids or i in {p['id'] for p in G['people']} for x in report['screened_but_not_queued'] for i in x.get('graph_ids',[]))
(OUT/'frameworks-review.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
print('Wrote',OUT/'frameworks-review.json')
